import {cabinet,rect,text,tile,colors,pick} from './cabinet.js';
export function createEcho(mount,api){const q=cabinet(mount,api,{accent:'#b9acff',height:440}),c=q.c;let sequence=[0,2,1],position=0,stage='watch',clock=.65,step=-1,lit=-1,glow=0,cursor=0;
 const notes=['one','two','three','four'];
 function reset(){sequence=[pick([0,1,2,3]),pick([0,1,2,3]),pick([0,1,2,3])];position=0;stage='watch';clock=.65;step=-1;lit=-1;glow=0;}
 function press(i){if(!q.active||stage!=='repeat')return;lit=i;glow=.25;q.sound(notes[i]);if(i!==sequence[position]){q.finish('Almost had it.',`${q.score} sequences echoed. Listen for each pad’s note.`);return;}position++;if(position===sequence.length){q.add(1);q.burst(180,205);q.say('PERFECT ECHO · one more note');stage='between';clock=1.1;}}
 return {start(){reset();q.start();},tap(p){p=q.local(p);const x=Math.floor((p.x-20)/162),y=Math.floor((p.y-62)/162);if(x>=0&&x<2&&y>=0&&y<2)press(y*2+x);},direction(d){cursor={up:0,right:1,left:2,down:3}[d];press(cursor);},action(){press(cursor);},tick(dt){q.frame(dt,dt=>{glow-=dt;if(glow<=0)lit=-1;if(stage==='repeat')return;clock-=dt;if(clock>0)return;if(stage==='between'){sequence.push(pick([0,1,2,3]));stage='watch';step=-1;position=0;clock=.35;return;}step++;if(step>=sequence.length){stage='repeat';lit=-1;q.say('YOUR TURN');return;}lit=sequence[step];glow=.38;q.sound(notes[lit]);clock=Math.max(.48,.75-q.score*.018);},()=>{q.header(`${sequence.length} NOTES`,stage==='repeat'?'YOUR TURN':'WATCH & LISTEN');for(let i=0;i<4;i++){const x=20+i%2*162,y=62+Math.floor(i/2)*162;tile(c,x+3,y+3,150,150,lit===i?'#f7f5ff':colors[i],['↑','→','←','↓'][i]);if(lit!==i){rect(c,x+3,y+3,150,150,'#111e3566',9);}text(c,i+1,x+24,y+27,14,lit===i?'#243647':'#ffffff',650);}q.footer(stage==='repeat'?`${position} / ${sequence.length} · repeat the pattern`:'Each pad has its own note.');});},destroy:q.destroy};}
